import pandas as pd
from analyze import cluster_stats

def test_negative_paired_mean():
    frame=pd.DataFrame({"day":["a","a","b","b"],"delta":[-.01,-.03,-.02,-.04]})
    assert abs(cluster_stats(frame,"delta")["mean"]+.025)<1e-12

import numpy as np
import pytest
from analyze import loss, align, contracts, pair, timed

def test_cluster_standard_error_not_row_independence():
    d=pd.DataFrame({"day":["a","a","b","b"],"delta":[-1.,-1.,1.,1.]})
    r=cluster_stats(d,"delta")
    assert r["mean"]==0 and r["se"]==1 and r["p"]==.5 and r["adjusted_p"]==1

def test_single_cluster_and_constant_scores_cannot_pass():
    for vals,groups in [([-1.,-1.],["a","a"]),([-1.,-1.],["a","b"])]:
        r=cluster_stats(pd.DataFrame({"day":groups,"delta":vals}),"delta")
        assert r["adjusted_p"]==1 and r["low"] is None

@pytest.mark.parametrize("p,y", [([np.nan],[1]),([-0.01],[1]),([1.01],[0]),([.5],[2])])
def test_invalid_probability_or_label_refused(p,y):
    with pytest.raises(ValueError):
        loss(p,y)

def test_scores_and_extreme_clipping():
    ll,bs=loss([0.,1.,.25],[1,0,1])
    np.testing.assert_allclose(ll,[-np.log(1e-6),-np.log(1e-6),-np.log(.25)],atol=1e-9)
    np.testing.assert_allclose(bs,[1,1,.5625])

def fixture():
    return pd.DataFrame([dict(ticker=t,lead_minutes=l,asset="ETH",probability_bin="10-20",decision_ms=1,
              settlement_ms=2,day="2026-05-02",band="w2",label=0,mid=.15)
              for t,l in [("a",2),("a",5),("b",2)]])

def test_align_handles_reordering_but_refuses_duplicate_missing_or_label_change():
    a=fixture()
    assert len(align(a,a.iloc[::-1]))==3
    for b in [a.iloc[:2],pd.concat([a,a.iloc[:1]]),a.assign(label=1)]:
        with pytest.raises((ValueError,AssertionError)):
            align(a,b)

def test_contract_weights_and_inconsistent_metadata():
    d=fixture().assign(week=1,half="first",month="2026-05",m_ll=[0.,0.,3.],m_bs=[0.,0.,1.],p_m=.5)
    assert contracts(d).m_ll.mean()==1.5
    d.loc[1,"day"]="2026-05-03"
    with pytest.raises(ValueError):
        contracts(d)

def test_existing_halves_and_boundaries():
    d=pd.DataFrame({"day":["2026-05-02","2026-06-15","2026-06-16","2026-07-31"]})
    p={"stages":{"validation":["2026-05-02","2026-08-01","2026-06-16"]}}
    assert timed(d,"validation",p).half.tolist()==["first","first","second","second"]
    with pytest.raises(ValueError):
        timed(pd.DataFrame({"day":["2026-08-01"]}),"validation",p)

def test_leave_one_week_reveals_single_week_dependence():
    d=pd.DataFrame({"day":["a","b","c","d"],"week":[1,2,3,4],"half":["first","first","second","second"],
                    "label":0,"p_a":.1,"p_b":.2,"a_ll":[-10.,1.,1.,1.],"b_ll":0.,"a_bs":0.,"b_bs":1.})
    r=pair(d,"a","b")
    assert r["daily"]["mean"]<0
    assert r["leave_week_out"][0]["mean"]==1
    assert not r["robust"]
